139	/** How a period is closed: shared by a close by hand ({@link ClosePeriod}) and the auto close of a
140	 *  today change ({@link AutoClosePeriods}). */
141	public final class PeriodClosing {
142	    private PeriodClosing() {
143	    }
144	
145	    /** Close the open period now, as a close by hand does (no permission check): used by the
146	     *  sheet's today change to close the periods past their grace days. */
147	    public static Period closeNow(Period found, String user, PeriodRepository periods, ClaimRepository claims,
148	            ClaimLogRepository log, PersonRepository people, RateRepository rates, SettingRepository settings,
149	            SheetRepository sheets) {
150	        return fixNow(found, user, false, periods, claims, log, people, rates, settings, sheets);
151	    }
152	
153	    /** Close or (soft) soft-close the period now, fixing its figures as they are now (no permission check). */
154	    public static Period fixNow(Period found, String user, boolean soft, PeriodRepository periods, ClaimRepository claims,
155	            ClaimLogRepository log, PersonRepository people, RateRepository rates, SettingRepository settings,
156	            SheetRepository sheets) {
157	        String id = found.sheetId();
158	        DatedSetting floor = settings.floor(id);
159	        Dues.Late late = settings.late(id, sheets.today(id));
160	        BigDecimal total = BigDecimal.ZERO.setScale(2);
161	        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
162	        for (Person p : people.list(id)) personTotals.put(p.getId(), BigDecimal.ZERO.setScale(2));
163	        Map<Long, String> atEnd = log.statusesOn(id, LocalDate.parse(found.to()));
164	        for (Claim c : claims.list(id)) {
165	            if (!found.contains(c.getDate())) continue;
166	            String status = atEnd.containsKey(c.getId()) ? atEnd.get(c.getId()) : c.getStatus();
167	            if (status == null || !(ClaimStatus.isOpen(status) || ClaimStatus.SETTLED.name().equals(status))) continue;
168	            Person person = people.find(id, c.getPersonId());
169	            if (person != null && person.leftOutLive(c)) continue;
170	            Rate rate = person == null ? null
171	                    : rates.find(id, person.gradeOn(c.getDate()), LocalDate.parse(c.getDate()));
172	            String due = Dues.shown(c, rate == null ? null : Dues.of(c.getAmount(), rate.pct(), late.rounding(c.getRoundDate())), floor.on(c.getDate()), late);
173	            if (due != null) {
174	                total = total.add(new BigDecimal(due));
175	                if (person != null) personTotals.merge(person.getId(), new BigDecimal(due), BigDecimal::add);
176	            }
177	        }
178	        return periods.close(found, total, personTotals, user, soft);
179	    }
