364	            // Deferred now: OPEN and deferred until a date after the sheet's today.
365	            + "(status = 'OPEN' AND deferred_until IS NOT NULL AND deferred_until > "
366	            + "(SELECT s.today FROM sheet s WHERE s.id = claim.sheet_id)) AS deferred, "
367	            // The date it rounds by: a correction's is the date of the claim it corrects.
368	            + "COALESCE((SELECT k.claim_date FROM claim k WHERE k.sheet_id = claim.sheet_id AND k.number = claim.corrects), "
369	            + "claim_date) AS round_date";
370	
371	    private static final RowMapper<Claim> ROW = (rs, n) -> withCorrects(new Claim(rs.getLong("id"),
372	            rs.getString("sheet_id"), rs.getLong("person_id"),
373	            rs.getBigDecimal("amount").setScale(2).toPlainString(),
374	            rs.getObject("claim_date", LocalDate.class).toString(), rs.getString("note"),
375	            rs.getString("status"), rs.getString("number"),
376	            rs.getBigDecimal("settled_due") == null ? null
377	                    : rs.getBigDecimal("settled_due").setScale(2).toPlainString(),
378	            rs.getString("opened_by"), rs.getBoolean("stated"),
379	            rs.getBigDecimal("stated_due") == null ? null
380	                    : rs.getBigDecimal("stated_due").setScale(2).toPlainString()), rs.getString("corrects"),
381	            rs.getObject("round_date", LocalDate.class).toString(),
382	            rs.getObject("due_by", LocalDate.class).toString(),
383	            rs.getObject("deferred_until", LocalDate.class), rs.getBoolean("deferred"), rs.getInt("proofs"), rs.getString("split_from"), rs.getString("locked_by"), rs.getBoolean("late_entry"));
384	
385	    private static Claim withCorrects(Claim claim, String corrects, String roundDate, String dueBy,
386	            LocalDate deferredUntil, boolean deferred, int proofs, String splitFrom, String lockedBy, boolean lateEntry) {
387	        claim.setLateEntry(lateEntry);
388	        claim.setLockedBy(lockedBy);
389	        claim.setSplitFrom(splitFrom);
390	        claim.setProofs(proofs);
391	        claim.setCorrects(corrects);
392	        claim.setDeferral(deferredUntil == null ? null : deferredUntil.toString(), deferred);
393	        claim.setDueBy(dueBy);
394	        claim.setRoundDate(roundDate);
395	        return claim;
396	    }
397	
398	    /** The next place in a sheet's list (newest first); takes the sheet id as its parameter. */
399	    private static final String NEXT_SEQ = "(SELECT COALESCE(MAX(k.list_seq), 0) + 1 FROM claim k WHERE k.sheet_id = ?)";
400	
401	    private final JdbcTemplate jdbc;
402	
403	    public ClaimRepository(JdbcTemplate jdbc) {
404	        this.jdbc = jdbc;
405	    }
406	
407	    /** The sheet's claims, newest first. */
408	    public List<Claim> list(String sheetId) {
409	        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? ORDER BY list_seq DESC, id DESC",
410	                ROW, sheetId);
411	    }
412	
413	    public Claim find(String sheetId, long id) {
414	        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?",
415	                ROW, sheetId, id).stream().findFirst().orElse(null);
416	    }
417	
418	    /** The claim on the sheet with that number; null when none has it. */
419	    public Claim findByNumber(String sheetId, String number) {
420	        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND number = ?",
421	                ROW, sheetId, number).stream().findFirst().orElse(null);
422	    }
423	
424	    /** Add a claim with its due-by, fixed now. */
425	    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
426	            String corrects, LocalDate dueBy, String user) {
427	        GeneratedKeyHolder key = new GeneratedKeyHolder();
428	        jdbc.update(con -> {
429	            PreparedStatement ps = con.prepareStatement(
430	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, created_by, corrects, due_by) "
431	                            + "VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
432	                    new String[] { "id" });
433	            ps.setString(1, sheetId);
434	            ps.setLong(2, personId);
435	            ps.setBigDecimal(3, amount);
436	            ps.setObject(4, date);
437	            ps.setString(5, note);
438	            ps.setString(6, user);
439	            ps.setObject(7, corrects);
440	            ps.setObject(8, dueBy);
441	            return ps;
442	        }, key);
443	        long id = key.getKey().longValue();
444	        jdbc.update("UPDATE claim SET list_seq = " + NEXT_SEQ + " WHERE sheet_id = ? AND id = ?", sheetId, sheetId, id);
445	        snapshot(sheetId, id);
446	        return find(sheetId, id);
447	    }
