449	    public void update(Claim claim) {
450	        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, number = ?, settled_due = ?, opened_by = ?, corrects = ? WHERE sheet_id = ? AND id = ?",
451	                new BigDecimal(claim.getAmount()), LocalDate.parse(claim.getDate()), claim.getNote(),
452	                claim.getStatus(), claim.getNumber(),
453	                claim.getSettledDue() == null ? null : new BigDecimal(claim.getSettledDue()),
454	                claim.getOpenedBy(), claim.getCorrects(),
455	                claim.getSheetId(), claim.getId());
456	        snapshot(claim.getSheetId(), claim.getId());
