459	    /** Save a claim moved to another person: its person, its binding (dropped), and its place in the
460	     *  list, now the newest. */
461	    public void reassign(Claim claim) {
462	        jdbc.update("UPDATE claim SET person_id = ?, stated = ?, stated_due = ?, list_seq = " + NEXT_SEQ
463	                + " WHERE sheet_id = ? AND id = ?",
464	                claim.getPersonId(), claim.isStated(),
465	                claim.getStatedDue() == null ? null : new BigDecimal(claim.getStatedDue()),
466	                claim.getSheetId(), claim.getSheetId(), claim.getId());
467	        snapshot(claim.getSheetId(), claim.getId());
