469	
470	    /** Save a re-dated claim: its date and its number (a new one when its period changed). */
471	    public void redate(Claim claim) {
472	        jdbc.update("UPDATE claim SET claim_date = ?, number = ? WHERE sheet_id = ? AND id = ?",
473	                LocalDate.parse(claim.getDate()), claim.getNumber(), claim.getSheetId(), claim.getId());
474	        snapshot(claim.getSheetId(), claim.getId());
475	    }
476	
477	    /** The person's claims, newest first. */
478	    public List<Claim> listOf(String sheetId, long personId) {
479	        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY list_seq DESC, id DESC",
480	                ROW, sheetId, personId);
