482	
483	    /** Keep the claim as it stands now in its history, with the sheet's today. */
484	    private void snapshot(String sheetId, long id) {
485	        jdbc.update("INSERT INTO claim_history (sheet_id, claim_id, on_date, person_id, amount, claim_date, status, "
486	                + "settled_due, stated, stated_due, deferred_until, due_by) SELECT c.sheet_id, c.id, s.today, c.person_id, "
487	                + "c.amount, c.claim_date, c.status, c.settled_due, c.stated, c.stated_due, c.deferred_until, c.due_by "
488	                + "FROM claim c JOIN sheet s ON s.id = c.sheet_id WHERE c.sheet_id = ? AND c.id = ?", sheetId, id);
489	    }
490	
491	    /** The person's claims as they stood at the end of the date, newest first: each as its last change
492	     *  made while the sheet's today was on or before the date left it (a claim of theirs then, and only
493	     *  claims there were then), deferred when OPEN and deferred until after the date. */
494	    public List<Claim> listOfAsOf(String sheetId, long personId, LocalDate asOf) {
495	        return jdbc.query("SELECT h.claim_id, h.person_id, h.amount, h.claim_date, h.status, h.settled_due, h.stated, "
496	                + "h.stated_due, h.deferred_until, h.due_by, c.note, c.number, c.opened_by, c.corrects, "
497	                + "COALESCE((SELECT k.claim_date FROM claim k WHERE k.sheet_id = c.sheet_id AND k.number = c.corrects), "
498	                + "h.claim_date) AS round_date FROM claim_history h JOIN claim c ON c.id = h.claim_id "
499	                + "WHERE h.sheet_id = ? AND h.person_id = ? AND h.id = (SELECT MAX(h2.id) FROM claim_history h2 "
500	                + "WHERE h2.claim_id = h.claim_id AND (h2.on_date IS NULL OR h2.on_date <= ?)) "
501	                + "ORDER BY c.list_seq DESC, c.id DESC", (rs, n) -> {
502	                    BigDecimal settled = rs.getBigDecimal("settled_due");
503	                    BigDecimal stated = rs.getBigDecimal("stated_due");
504	                    LocalDate until = rs.getObject("deferred_until", LocalDate.class);
505	                    String status = rs.getString("status");
506	                    Claim claim = new Claim(rs.getLong("claim_id"), sheetId, rs.getLong("person_id"),
507	                            rs.getBigDecimal("amount").setScale(2).toPlainString(),
508	                            rs.getObject("claim_date", LocalDate.class).toString(), rs.getString("note"), status,
509	                            rs.getString("number"), settled == null ? null : settled.setScale(2).toPlainString(),
510	                            rs.getString("opened_by"), rs.getBoolean("stated"),
511	                            stated == null ? null : stated.setScale(2).toPlainString());
512	                    return withCorrects(claim, rs.getString("corrects"),
513	                            rs.getObject("round_date", LocalDate.class).toString(),
514	                            rs.getObject("due_by", LocalDate.class).toString(), until,
515	                            ClaimStatus.OPEN.name().equals(status) && until != null && until.isAfter(asOf),
516	                            0, null, null, false);
517	                }, sheetId, personId, asOf);
518	    }
519	
520	    /** Save the date a claim is deferred until. */
521	    public void updateDeferral(Claim claim) {
522	        jdbc.update("UPDATE claim SET deferred_until = ? WHERE sheet_id = ? AND id = ?",
523	                claim.getDeferredUntil() == null ? null : LocalDate.parse(claim.getDeferredUntil()),
524	                claim.getSheetId(), claim.getId());
525	        snapshot(claim.getSheetId(), claim.getId());
526	    }
527	
528	    /** Save the number of the claim a claim was split from. */
529	    public void updateSplitFrom(Claim claim) {
530	        jdbc.update("UPDATE claim SET split_from = ? WHERE sheet_id = ? AND id = ?",
531	                claim.getSplitFrom(), claim.getSheetId(), claim.getId());
532	    }
533	
534	    /** Save a claim's proofs count. */
535	    public void updateProofs(Claim claim) {
536	        jdbc.update("UPDATE claim SET proofs = ? WHERE sheet_id = ? AND id = ?",
537	                claim.getProofs(), claim.getSheetId(), claim.getId());
538	    }
539	
540	    /** Save a claim's binding by its person's last statement. */
541	    public void updateBinding(Claim claim) {
542	        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE sheet_id = ? AND id = ?",
543	                claim.isStated(), claim.getStatedDue() == null ? null : new BigDecimal(claim.getStatedDue()),
544	                claim.getSheetId(), claim.getId());
545	        snapshot(claim.getSheetId(), claim.getId());
546	    }
547	
548	    /** The sheet's next claim number, taken in one atomic statement so two claims opened at the same
549	     *  moment never get the same one; rolled back with the request when it is refused. */
550	    public String nextNumber(String sheetId) {
551	        return String.valueOf(jdbc.queryForObject("SELECT last_claim_number FROM FINAL TABLE ("
552	                + "UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?)",
553	                Long.class, sheetId));
554	    }
555	
556	    /** The next number in a period's own sequence on the sheet ({@code <period>-<n>}, from 1), or
557	     *  for a claim in no period ({@code period} null) in the X sequence ({@code X-<n>}); taken
558	     *  atomically as {@link #nextNumber} is. */
559	    public String nextPeriodNumber(String sheetId, String period) {
560	        String key = period == null ? "" : period;
561	        try {
562	            jdbc.update("INSERT INTO sheet_period_number (sheet_id, period_key) SELECT ?, ? WHERE NOT EXISTS "
563	                    + "(SELECT 1 FROM sheet_period_number WHERE sheet_id = ? AND period_key = ?)",
564	                    sheetId, key, sheetId, key);
565	        } catch (DuplicateKeyException raced) {
566	            // Another request started the sequence at the same moment.
567	        }
568	        Long n = jdbc.queryForObject("SELECT last_number FROM FINAL TABLE (UPDATE sheet_period_number "
569	                + "SET last_number = last_number + 1 WHERE sheet_id = ? AND period_key = ?)",
570	                Long.class, sheetId, key);
571	        return (period == null ? "X" : period) + "-" + n;
572	    }
573	
574	    /** Mark a claim as a late entry: added while the period its date falls in was soft-closed. */
575	    public void markLateEntry(Claim claim) {
576	        jdbc.update("UPDATE claim SET late_entry = TRUE WHERE sheet_id = ? AND id = ?", claim.getSheetId(), claim.getId());
577	        claim.setLateEntry(true);
578	    }
579	
580	    /** Lock a claim for the user opening its editor, releasing any other claim of the same person that
581	     *  user held. */
582	    public void lock(Claim claim, String user) {
583	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND person_id = ? AND locked_by = ? AND id <> ?",
584	                claim.getSheetId(), claim.getPersonId(), user, claim.getId());
585	        jdbc.update("UPDATE claim SET locked_by = ? WHERE sheet_id = ? AND id = ?", user, claim.getSheetId(), claim.getId());
586	        claim.setLockedBy(user);
587	    }
588	
589	    /** Release a claim's lock when {@code user} holds it (null: whoever holds it). */
590	    public void unlock(Claim claim, String user) {
591	        if (user == null || user.equals(claim.getLockedBy())) {
592	            jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND id = ?", claim.getSheetId(), claim.getId());
593	            claim.setLockedBy(null);
594	        }
595	    }
596	
597	    /** Release every claim lock on the sheet. */
598	    public void unlockAll(String sheetId) {
599	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND locked_by IS NOT NULL", sheetId);
600	    }
601	}
602	package net.officefloor.hq.app.claim;
603	
604	import java.math.BigDecimal;
605	import java.math.RoundingMode;
606	import java.time.LocalDate;
607	import java.time.temporal.ChronoUnit;
608	import net.officefloor.hq.app.setting.DatedSetting;
609	
610	/** A claim's due figure. */
611	public final class Dues {
612	    private Dues() {
613	    }
614	
615	    /** What a late charge goes by: the sheet's late percent by date (a charge goes by the one in force on each 30-day boundary) and its today (a claim's due-by is its own); and the
616	     *  sheet's policy date (its today when blank), which decides how a claim's live figures round. */
617	    public record Late(DatedSetting pct, LocalDate today, LocalDate policy) {
618	
619	        /** How the live figures of a claim round by its round date ({@link Claim#getRoundDate}):
620	         *  half up before the policy date, half to even on or after it. */
621	        public RoundingMode rounding(String roundDate) {
622	            return LocalDate.parse(roundDate).isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
623	        }
624	    }
625	
626	    /** A claim's rate figure: an amount times a percent, divided by 100, rounded ({@code rounding}) to
627	     *  two decimals (no floor: that is applied last, by {@link #shown}). */
628	    public static String of(String amount, String pct, RoundingMode rounding) {
629	        return new BigDecimal(amount).multiply(new BigDecimal(pct))
630	                .divide(BigDecimal.valueOf(100), 2, rounding).toPlainString();
631	    }
632	
633	    /** Whether a claim's amount makes it a correction: it is negative. */
634	    public static boolean isCorrection(String amount) {
635	        return new BigDecimal(amount).signum() < 0;
636	    }
637	
638	    /** The late charge on a claim's figure: for each full 30 days its open (OPEN or PENDING) claim is past its
639	     *  due-by (fixed when it was added) on the sheet's today, the late percent in force on that boundary date
640	     *  (its due-by plus 30, 60, 90 ... days) of it, each rounded by the policy date to two decimals, added up;
641	     *  none (0.00) when it is not overdue (a deferred claim never is), or on a correction. */
642	    public static BigDecimal charge(Claim claim, String figure, Late late) {
643	        BigDecimal total = BigDecimal.ZERO.setScale(2);
644	        if (figure == null || isCorrection(claim.getAmount()) || !ClaimStatus.isOpen(claim.getStatus()) || claim.isDeferred()) return total;
645	        LocalDate dueBy = LocalDate.parse(claim.getDueBy());
646	        long periods = Math.max(0, ChronoUnit.DAYS.between(dueBy, late.today())) / 30;
647	        RoundingMode rounding = late.rounding(claim.getRoundDate());
648	        for (long k = 1; k <= periods; k++) {
649	            String pct = late.pct().on(dueBy.plusDays(30 * k).toString());
650	            if (pct == null) continue;
651	            total = total.add(new BigDecimal(figure).multiply(new BigDecimal(pct))
652	                    .divide(BigDecimal.valueOf(100), 2, rounding));
653	        }
654	        return total;
655	    }
656	
657	    /** The due a claim shows: the one fixed when settled, else its figure (bound by a statement, else
658	     *  {@code live}; null: none) with its late charge added on top, and at least {@code floor}, the sheet's
659	     *  floor in force on the claim's date (null: none), applied last (a correction has no floor). */
660	    public static String shown(Claim claim, String live, String floor, Late late) {
661	        if (claim.getSettledDue() != null) return claim.getSettledDue();
662	        String figure = claim.due(live);
663	        if (figure == null) return null;
664	        BigDecimal due = new BigDecimal(figure).add(charge(claim, figure, late));
665	        if (floor != null && !isCorrection(claim.getAmount())) due = due.max(new BigDecimal(floor).setScale(2));
666	        return due.toPlainString();
667	    }
668	}
669	package net.officefloor.hq.app.claim;
670	
671	import java.time.LocalDate;
672	import net.officefloor.hq.app.period.Period;
673	import net.officefloor.hq.app.period.PeriodRepository;
674	import net.officefloor.hq.app.setting.SettingRepository;
675	import net.officefloor.hq.app.sheet.SheetRepository;
676	
677	/** The number a claim gets when opened: while the sheet's period numbering is in force (its
678	 *  period-numbering-from is a date on or before the sheet's today) the next in the sequence of the
679	 *  period its date falls in ({@code <period>-<n>}; {@code X-<n>} in no period), else the sheet's next. */
680	public final class ClaimNumbers {
681	    private ClaimNumbers() {
682	    }
683	
684	    public static String next(Claim claim, ClaimRepository claims, PeriodRepository periods,
685	            SettingRepository settings, SheetRepository sheets) {
686	        String sheetId = claim.getSheetId();
687	        LocalDate from = settings.periodNumberingFrom(sheetId);
688	        if (from == null || sheets.today(sheetId).isBefore(from)) {
689	            return claims.nextNumber(sheetId);
690	        }
691	        String period = periods.list(sheetId).stream().filter((p) -> p.contains(claim.getDate()))
692	                .map(Period::name).findFirst().orElse(null);
693	        return claims.nextPeriodNumber(sheetId, period);
694	    }
695	}
